 void paintTrips(){if(tripChoices==null||!page.equals("form"))return;tripChoices.removeAllViews();int count=activeTrips(inputs.get("course").getText().toString());for(int n=1;n<=5;n++){if(n>count&&!(editId!=null&&n==trip))continue;final int selected=n;button(tripChoices,tripName(n)+(n>count?" (tidligere tur)":""),()->{if(tripClock.running&&selected!=trip){alert("Stopp tidtakingen før du bytter tur.");return;}if(distributionRun!=null&&selected!=trip){alert("Nullstill distribusjonsloggen eller velg Ny tur før du bytter tur.");return;}trip=selected;paintTrips();persistDraft();},n==trip);}paintDistribution();}
 void courseSetup(String course){if(!requireLogin())return;LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);EditText input=setupField(panel,"Kursnavn",course,false);Spinner count=new Spinner(this);count.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"1 aktiv tur","2 aktive turer","3 aktive turer","4 aktive turer","5 aktive turer"}));count.setSelection(activeTrips(course)-1);panel.addView(count);JSONObject old=courseDistribution(course);EditText stops=setupField(panel,"Antall distribusjonsstopp (0–30; 0 = av)",old==null?"0":old.optString("stop_count","0"),true);EditText total=setupField(panel,"Forventet totaltid skole → skole (minutter)",old==null?"0":old.optString("expected_minutes","0"),true);ScrollView view=new ScrollView(this);view.addView(panel);dialog().setTitle("Kursoppsett").setView(view).setNegativeButton("Avbryt",null).setPositiveButton("Lagre",(d,w)->{try{int n=Integer.parseInt(stops.getText().toString().trim());double t=Double.parseDouble(total.getText().toString().trim().replace(',','.'));double[] values=DistributionRun.validatePlan(n,t,new double[0]);JSONObject plan=new JSONObject().put("stop_count",n).put("expected_minutes",t).put("deadlines",new JSONArray(values));manageAction(new JSONObject().put("action","course_setup_save").put("name",input.getText().toString().trim()).put("active_trips",count.getSelectedItemPosition()+1).put("distribution_plan",plan));}catch(Exception e){alert(e.getMessage());}}).show();}
