 long seenDistributionVersion=0;
 void refreshDistribution(){if(!page.equals("form")||!inputs.containsKey("minutes"))return;android.content.SharedPreferences p=getSharedPreferences("draft",0);long version=p.getLong("distribution_version",0);if(version==seenDistributionVersion)return;try{JSONObject d=new JSONObject(p.getString("payload","{}"));restoreDistribution(d.optJSONObject("distribution"));seenDistributionVersion=version;if(distributionRun!=null&&distributionRun.finishedMillis>=0)inputs.get("minutes").setText(String.format(Locale.ROOT,"%.4f",distributionRun.finishedMillis/60000.0));paintDistribution();}catch(Exception e){alert(e.getMessage());}}
 void menuDistribution(int action){continueForm();if(!page.equals("form")||distributionRun==null||distributionRun.finishedMillis>=0)return;if(action==9)requestFinishDistribution();else if(distributionRun.events.size()<distributionRun.deadlines.length){if(action==7)recordRamp();else abortDistributionStop();}}
 void freezeDistribution(){if(!page.equals("form"))return;for(String k:new String[]{"driver","course","vehicle","minutes","date","start_time"})if(inputs.containsKey(k))inputs.get(k).setEnabled(distributionRun==null);}
 void startDistribution(){try{if(tripClock.running)throw new Exception("Stopp den andre tidtakingen først.");for(String k:new String[]{"driver","course","vehicle"})if(inputs.get(k).getText().toString().trim().isEmpty())throw new Exception("Velg sjåfør, kurs og bil før Start.");JSONObject p=courseDistribution(inputs.get("course").getText().toString());if(p==null||p.optInt("stop_count")==0)throw new Exception("Admin må angi stopp og forventet tid i kursoppsettet først.");TimerService.dismiss(this);tripClock.reset();persistClock();long now=System.currentTimeMillis();distributionRun=new DistributionRun(p.getDouble("expected_minutes"),deadlineArray(p.getJSONArray("deadlines")),now,SystemClock.elapsedRealtime(),boot());inputs.get("date").setText(new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date(now)));inputs.get("start_time").setText(new SimpleDateFormat("HH:mm",Locale.ROOT).format(new Date(now)));freezeDistribution();persistDraft();paintDistribution();notificationTimer();}catch(Exception e){alert(e.getMessage());}}
 void markDistribution(String state,String reason){try{refreshDistribution();distributionRun.mark(state,reason,SystemClock.elapsedRealtime(),System.currentTimeMillis(),boot());persistDraft();paintDistribution();if(TimerService.active)TimerService.show(this,"show");}catch(Exception e){alert(e.getMessage());}}
 void recordRamp(){refreshDistribution();if(distributionRun==null||distributionRun.finishedMillis>=0||distributionRun.events.size()>=distributionRun.deadlines.length)return;int stop=distributionRun.events.size()+1;markDistribution("ramp","");if(distributionRun.events.size()>=stop)commentDistribution(stop);}
 void commentDistribution(int stop){refreshDistribution();if(distributionRun==null||stop>distributionRun.events.size())return;final long start=distributionRun.startedWall;EditText note=new EditText(this);note.setHint("Kommentar til rampe/stopp (valgfritt, maks 300 tegn)");note.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);note.setText(distributionRun.events.get(stop-1).reason);dialog().setTitle("Kommentar · stopp "+stop).setView(note).setNegativeButton("Lukk",null).setPositiveButton("Lagre kommentar",(d,w)->{try{refreshDistribution();if(distributionRun==null||distributionRun.startedWall!=start)throw new Exception("Turen er endret.");distributionRun.comment(stop,note.getText().toString().trim());persistDraft();paintDistribution();}catch(Exception e){alert(e.getMessage());}}).show();}
 void requestFinishDistribution(){dialog().setTitle("Avslutt tur ved skolen?").setMessage("Avslutt først når bilen er tilbake ved skolen. Returen inngår i totaltiden fra skole til skole.").setNegativeButton("Fortsett retur",null).setPositiveButton("Tilbake ved skolen",(d,w)->finishDistribution()).show();}
