 String stopLine(DistributionRun.Event e,long prior){double total=e.elapsedMillis/60000.0;return String.format(Locale.getDefault(),"Stopp %d · %s\nFra forrige: %.1f min · Fra start: %.1f min%s",e.stop,e.status.equals("ramp")?"Rygget til rampe":"AVBRUTT",(e.elapsedMillis-prior)/60000.0,total,e.reason.isEmpty()?"":"\nKommentar: "+e.reason);}
 void paintDistributionClock(){if(!page.equals("form")||trip!=4||distributionRun==null||distributionLive==null)return;DistributionRun r=distributionRun;double actual=r.elapsed(SystemClock.elapsedRealtime(),System.currentTimeMillis(),boot())/60000.0;String line=String.format(Locale.getDefault(),"%s · %.1f min fra start\nForventet skole → skole: %.1f min",r.finishedMillis>=0?"Avsluttet":"Pågår",actual,r.expectedMinutes);if(r.finishedMillis<0&&r.events.size()<r.deadlines.length)line+="\nNeste: stopp "+(r.events.size()+1);if(r.events.size()==r.deadlines.length)line+=String.format(Locale.getDefault(),"\n%s · siste stopp → skole: %.1f min",r.finishedMillis>=0?"Retur registrert":"Retur pågår",r.returnMillis(SystemClock.elapsedRealtime(),System.currentTimeMillis(),boot())/60000.0);if(r.finishedMillis<0)line+="\n"+r.remainingText(Math.round(actual*60000));distributionLive.setText(line);}
 void paintDistribution(){if(!page.equals("form"))return;JSONObject config=inputs.containsKey("course")?courseDistribution(inputs.get("course").getText().toString()):null;boolean delivery=trip==4&&(distributionRun!=null||config!=null&&config.optInt("stop_count")>0);if(regularClock!=null)regularClock.setVisibility(delivery?View.GONE:View.VISIBLE);if(distributionHost==null)return;distributionHost.setVisibility(trip==4?View.VISIBLE:View.GONE);distributionHost.removeAllViews();distributionLive=null;if(trip!=4)return;distributionHost.addView(text("DISTRIBUSJON · LEVERINGSSTOPP",17,TEAL));distributionHost.addView(text("Start ved skolen. Avslutt når bilen er tilbake ved skolen. Tiden inkluderer lasting, venting, pauser og retur. Leveringsstopp telles separat fra unødige stopp.",13,MUTED));if(distributionRun==null){JSONObject p=courseDistribution(inputs.get("course").getText().toString());int n=p==null?0:p.optInt("stop_count");distributionHost.addView(text(n==0?"Ingen stoppplan. Admin kan sette den i Kursoppsett.":n+" stopp · forventet totalt "+p.optDouble("expected_minutes")+" min",16,TEXT));button(distributionHost,"Start distribusjonsoppdrag",()->startDistribution(),true);return;}distributionLive=text("",18,TEAL);distributionHost.addView(distributionLive);paintDistributionClock();long prior=0;for(DistributionRun.Event e:distributionRun.events){distributionHost.addView(text(stopLine(e,prior),15,e.status.equals("aborted")?Color.rgb(255,138,149):TEXT));final int stop=e.stop;button(distributionHost,"Kommentar til stopp "+stop,()->commentDistribution(stop),false);prior=e.elapsedMillis;}if(distributionRun.finishedMillis<0){if(distributionRun.events.size()<distributionRun.deadlines.length){int n=distributionRun.events.size()+1;button(distributionHost,"Stopp "+n+": Rygget til rampe",()->recordRamp(),true);button(distributionHost,"Avbryt stopp "+n+" …",()->abortDistributionStop(),false);}else button(distributionHost,"Tilbake ved skolen: Avslutt tur",()->requestFinishDistribution(),true);}button(distributionHost,"Nullstill distribusjonslogg …",()->dialog().setTitle("Nullstill distribusjonslogg?").setMessage("Starttid og alle registrerte leveringsstopp slettes fra dette utkastet.").setNegativeButton("Avbryt",null).setPositiveButton("Nullstill",(d,w)->{refreshDistribution();TimerService.dismiss(this);distributionRun=null;freezeDistribution();persistDraft();paintDistribution();}).show(),false);freezeDistribution();}
 Spinner feedbackType;String feedbackId;
