 interface FeedbackResult {void accept(JSONObject result)throws Exception;}
 void feedbackRequest(JSONObject request,FeedbackResult callback){if(!requireLogin()||adminBusy)return;adminBusy=true;feedbackEnabled(false);status.setText("Oppdaterer tilbakemelding …");new Thread(()->{try{JSONObject result=Sync.admin(this,request);runOnUiThread(()->{adminBusy=false;feedbackEnabled(true);if(isDestroyed()||!authenticated)return;try{callback.accept(result);}catch(Exception e){alert(e.getMessage());}});}catch(Exception e){runOnUiThread(()->{adminBusy=false;feedbackEnabled(true);if(!isDestroyed()&&authenticated)alert(e.getMessage());});}},"YSK-feedback").start();}
 void feedbackForm(){if(!requireLogin())return;persistDraft();persistFeedback();page="feedback";clockView=null;body.removeAllViews();inputs.clear();JSONObject d=new JSONObject();try{d=new JSONObject(getSharedPreferences("feedback",0).getString("draft","{}"));}catch(Exception ignored){}feedbackId=d.optString("id",UUID.randomUUID().toString());body.addView(text("Tilbakemelding",23,TEXT));feedbackType=new Spinner(this);feedbackType.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Tilbakemelding / forslag","Feilmelding"}));feedbackType.setSelection(d.optInt("kind",0));body.addView(feedbackType);field("feedback_title","Tittel (maks 120 tegn)",d.optString("title"),false,false);EditText message=field("feedback_body","Beskriv forslaget eller feilen (maks 4000 tegn)",d.optString("body"),false,false);message.setSingleLine(false);message.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);message.setMinLines(5);body.addView(text("Navn, appversjon, telefonmodell og Android-versjon følger med. Lagres i skolens adminpanel; videresendes til Discord hvis konfigurert. Utkastet beholdes ved nettfeil.",13,MUTED));button(body,"Send tilbakemelding",()->sendFeedback(),true);persistFeedback();}
 void sendFeedback(){if(adminBusy)return;persistFeedback();try{String title=inputs.get("feedback_title").getText().toString().trim(),message=inputs.get("feedback_body").getText().toString().trim();if(title.isEmpty()||title.length()>120||message.isEmpty()||message.length()>4000)throw new Exception("Tittel: 1–120 tegn. Melding: 1–4000 tegn.");android.content.pm.PackageInfo info=getPackageManager().getPackageInfo(getPackageName(),0);JSONObject request=new JSONObject().put("action","feedback_submit").put("id",feedbackId).put("kind",feedbackType.getSelectedItemPosition()==0?"suggestion":"bug").put("title",title).put("body",message).put("platform","android").put("version",info.versionName+" / B"+updates.installed()).put("device",Build.MANUFACTURER+" "+Build.MODEL+" · Android "+Build.VERSION.RELEASE);feedbackRequest(request,result->{getSharedPreferences("feedback",0).edit().clear().commit();if(page.equals("feedback")){page="";feedbackForm();}Toast.makeText(this,result.optString("message"),Toast.LENGTH_LONG).show();});}catch(Exception e){alert(e.getMessage());}}
 AlertDialog feedbackInboxDialog;
 String feedbackStatus(String value){return value.equals("open")?"Ny":value.equals("working")?"Under behandling":"Ferdig";}
