 int feedbackOffset=0;
 void feedbackInbox(){try{feedbackRequest(new JSONObject().put("action","feedback_list").put("offset",feedbackOffset),result->{LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);JSONArray rows=result.getJSONArray("rows");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);panel.addView(text((row.optString("kind").equals("bug")?"FEIL":"FORSLAG")+" · "+row.optString("title"),18,TEXT));panel.addView(text(row.optString("author")+" · "+row.optString("platform")+" "+row.optString("version")+"\nStatus: "+feedbackStatus(row.optString("status"))+" · Discord: "+feedbackDelivery(row.optString("delivery")),13,MUTED));button(panel,"Les melding",()->dialog().setTitle(row.optString("title")).setMessage(row.optString("body")+"\n\nEnhet: "+row.optString("device")+"\n"+row.optString("delivery_error")).setPositiveButton("Lukk",null).show(),false);LinearLayout states=new LinearLayout(this);panel.addView(states);String[] keys={"open","working","resolved"},labels={"Ny","Behandles","Ferdig"};for(int j=0;j<keys.length;j++){final String key=keys[j];button(states,labels[j],()->feedbackChange(row.optString("id"),"feedback_status",key),false);}button(panel,"Prøv Discord på nytt",()->feedbackChange(row.optString("id"),"feedback_retry",null),false);}if(rows.length()==0)panel.addView(text("Ingen meldinger på denne siden.",16,TEXT));button(panel,"Discord · to webhooks",()->feedbackHooks(),true);LinearLayout pages=new LinearLayout(this);panel.addView(pages);button(pages,"← Forrige",()->{feedbackOffset=Math.max(0,feedbackOffset-100);feedbackInbox();},false);button(pages,"Neste →",()->{feedbackOffset+=100;feedbackInbox();},false);ScrollView view=new ScrollView(this);view.addView(panel);if(feedbackInboxDialog!=null)feedbackInboxDialog.dismiss();feedbackInboxDialog=dialog().setTitle("Admin · Tilbakemeldinger").setView(view).setPositiveButton("Lukk",null).show();});}catch(Exception e){alert(e.getMessage());}}
 void feedbackChange(String id,String action,String value){try{JSONObject request=new JSONObject().put("action",action).put("id",id);if(value!=null)request.put("status",value);feedbackRequest(request,r->{Toast.makeText(this,r.optString("message"),Toast.LENGTH_LONG).show();if(feedbackInboxDialog!=null&&feedbackInboxDialog.isShowing())feedbackInbox();});}catch(Exception e){alert(e.getMessage());}}
 void feedbackHooks(){try{feedbackRequest(new JSONObject().put("action","feedback_hooks_get"),result->{LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);Map<String,EditText> urls=new HashMap<>();Map<String,CheckBox> disable=new HashMap<>();JSONArray hooks=result.getJSONArray("hooks");for(int i=0;i<hooks.length();i++){JSONObject hook=hooks.getJSONObject(i);String key=hook.getString("kind");panel.addView(text((key.equals("bug")?"Feilmelding":"Tilbakemelding / forslag")+(hook.getBoolean("enabled")?" · konfigurert":" · ikke konfigurert"),16,TEXT));EditText input=new EditText(this);input.setHint("Lim inn ny Discord-webhook");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);panel.addView(input);urls.put(key,input);CheckBox off=new CheckBox(this);off.setText("Deaktiver webhook");off.setTextColor(TEXT);panel.addView(off);disable.put(key,off);}panel.addView(text("Tomt felt beholder eksisterende webhook.",13,MUTED));dialog().setTitle("Discord-webhooks · egen skole").setView(panel).setNegativeButton("Avbryt",null).setPositiveButton("Lagre",(d,w)->{if(adminBusy)return;adminBusy=true;Map<String,String> changes=new HashMap<>();for(String key:urls.keySet())if(disable.get(key).isChecked()||!urls.get(key).getText().toString().trim().isEmpty())changes.put(key,disable.get(key).isChecked()?"":urls.get(key).getText().toString().trim());new Thread(()->{try{for(Map.Entry<String,String> e:changes.entrySet())Sync.admin(this,new JSONObject().put("action","feedback_hooks_save").put("kind",e.getKey()).put("url",e.getValue()));runOnUiThread(()->{adminBusy=false;if(authenticated)Toast.makeText(this,"Webhook-innstillinger lagret",Toast.LENGTH_LONG).show();});}catch(Exception e){runOnUiThread(()->{adminBusy=false;if(authenticated)alert(e.getMessage());});}},"YSK-feedback-hooks").start();}).show();});}catch(Exception e){alert(e.getMessage());}}
