 public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);persistDraft();if(page.equals("form"))try{out.putString("draft",draft().toString());}catch(Exception ignored){}}
 public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code==42&&results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)TimerService.show(this,"show");}
 public void onResume(){super.onResume();restoreClock();timer.removeCallbacks(clockTick);timer.post(clockTick);timer.post(tick);updateStatus();if(authenticated)updates.automatic();}
 public void onPause(){if(paramTrips!=null)paramTrips.persist();persistFeedback();persistDraft();super.onPause();timer.removeCallbacks(tick);timer.removeCallbacks(clockTick);}
 public void onDestroy(){dismissDialogs();timer.removeCallbacks(clockTick);timer.removeCallbacks(tick);db.close();super.onDestroy();}
 int boot(){return android.provider.Settings.Global.getInt(getContentResolver(),android.provider.Settings.Global.BOOT_COUNT,0);}
 long clockMillis(){return tripClock.elapsed(SystemClock.elapsedRealtime(),System.currentTimeMillis(),boot());}
 void restoreClock(){tripClock=TimerService.load(this);}
 void persistClock(){TimerService.store(this,tripClock);}
 void notificationTimer(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},42);TimerService.show(this,"show");}
 JSONObject draft()throws Exception{JSONObject d=new JSONObject();for(Map.Entry<String,EditText> e:inputs.entrySet())d.put(e.getKey(),e.getValue().getText().toString());for(String k:QUAL)d.put(k,ratings.get(k));d.put("trip",trip);if(editId!=null)d.put("id",editId);if(managedEdit!=null)d.put("_managed",managedEdit);if(distributionRun!=null)d.put("distribution",distributionJson(true));return d;}
